def total(nums):
    if not nums:
        return 0
    return nums[0] + total(nums[1:])

print(total([4, 2, 3]))

from collections import deque

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D', 'E'], 'D': ['F'], 'E': ['F'], 'F': []}
dist = {'A': 0}
queue = deque(['A'])
while queue:
    node = queue.popleft()
    for nxt in graph[node]:
        if nxt not in dist:
            dist[nxt] = dist[node] + 1
            queue.append(nxt)
print(dist)
